Someone rearranged the status chain from step 5. With these numbers, what does it print?
js
const income = 8000;
const left = -500;
let status;
if (left income 0.2) {
 status = "healthy";
} else if (left <= income 0.2) {
 status = "tight";
} else if (left < 0) {
 status = "overspent";
}
console.log(status);
- [ ] overspent
- [ ] healthy
