 const lineTotal = quantity unitPrice;
 let label = item;
 if (quantity 1) {
 const plural = "s";
 label = item + plural;
 }
 return ${quantity} ${label}: R${lineTotal};
}
console.log(shopName);
for (let day = 1; day <= 2; day++) {
 const line = receiptLine("samoosa", day 3, 7);
 console.log(Day ${day}: ${line});
