Follow the shape of loadNotes/saveNotes from the notes program. The difference is that each item in the list is an object instead of a string, so totalFares uses the accumulator pattern with trip.fare, as in Lists of objects.


js
const prompt = require("prompt-sync")();
const fs = require("fs");
const FILE = "fares.json";
function loadTrips() {
 if (!fs.existsSync(FILE)) {
 return [];
 }
 return JSON.parse(fs.readFileSync(FILE, "utf8"));
}
function saveTrips(trips) {
 fs.writeFileSync(FILE, JSON.stringify(trips, null, 2));
}
function totalFares(trips) {
 let total = 0;
 for (const trip of trips) {
 total += trip.fare;
 }
 return total;
}
